async function main() {
  const issues: any[] = [];
  let page: number | null = 1;
  while (page) {
    const r = await tools.list_issues({ repo: "acme/web", state: "open", label: "perf", page });
    issues.push(...r.items);
    page = r.next_page;
  }
  const summary = issues.map(i => ({
    number: i.number,
    state: i.state,
    labels: i.labels.map((l: any) => l.name),
    assignee: i.assignee ? i.assignee.login : null,
  }));
  return summary;
}
return await main();
```

